// Package model defines the task type.
package model

import (
	"errors"
	"regexp"
	"sort"
	"strings"
	"time"
)

// Task is one tracked item.
type Task struct {
	ID       int        `json:"id"`
	Title    string     `json:"title"`
	Priority int        `json:"priority"`
	Done     bool       `json:"done"`
	Created  time.Time  `json:"created"`
	Tags     []string   `json:"tags,omitempty"`
	Due      *time.Time `json:"due,omitempty"`
}

// Validation errors.
var (
	ErrEmptyTitle  = errors.New("title must not be empty")
	ErrBadPriority = errors.New("priority must be between 1 and 5")
	ErrBadTag      = errors.New("bad tag")
)

// DefaultPriority is used when none is given.
const DefaultPriority = 3

var tagPattern = regexp.MustCompile(`^[a-z0-9][a-z0-9-]*$`)

// NormalizeTag trims and lower-cases a tag, and reports whether it is
// usable: it must match "^[a-z0-9][a-z0-9-]*$".
func NormalizeTag(tag string) (string, error) {
	s := strings.ToLower(strings.TrimSpace(tag))
	if !tagPattern.MatchString(s) {
		return "", ErrBadTag
	}
	return s, nil
}

// DueDate converts a date to the canonical stored form: UTC midnight.
func DueDate(d time.Time) time.Time {
	return time.Date(d.Year(), d.Month(), d.Day(), 0, 0, 0, 0, time.UTC)
}

// Validate checks the task fields, normalising tags and the due date.
func (t *Task) Validate() error {
	t.Title = strings.TrimSpace(t.Title)
	if t.Title == "" {
		return ErrEmptyTitle
	}
	if t.Priority < 1 || t.Priority > 5 {
		return ErrBadPriority
	}
	seen := map[string]bool{}
	var tags []string
	for _, g := range t.Tags {
		g, err := NormalizeTag(g)
		if err != nil {
			return ErrBadTag
		}
		if !seen[g] {
			seen[g] = true
			tags = append(tags, g)
		}
	}
	sort.Strings(tags)
	t.Tags = tags
	if t.Due != nil {
		t.Due = &model... // careful: time value
	}
	return nil
}
