{"content":"// Package query filters and sorts tasks.
package query

import (
	"fmt"
	"sort"
	"time"

	"example.com/tasker/internal/model"
)

// Options selects and orders tasks.
type Options struct {
	IncludeDone bool
	SortBy      string   // "id" (default), "priority" or "due"
	Tags        []string // only tasks having ALL these tags
	Overdue     bool     // only open tasks due strictly before Today
	Today       time.Time // UTC midnight, used for Overdue
}

func hasAllTags(t model.Task, want []string) bool {
	for _, w := range want {
		found := false
		for _, g := range t.Tags {
			if g == w {
				found = true
				break
			}
		}
		if !found {
			return false
		}
	}
	return true
}

// Apply returns the matching tasks in order.
func Apply(tasks []model.Task, o Options) ([]model.Task, error) {
	var out []model.Task
	for _, t := range tasks {
		if t.Done && !o.IncludeDone {
			continue
		}
		if o.Overdue && (t.Done || t.Due == nil || !t.Due.Before(o.Today)) {
			continue
		}
		if !hasAllTags(t, o.Tags) {
			continue
		}
		out = append(out, t)
	}
	switch o.SortBy {
	case "", "id":
		sort.SliceStable(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	case "priority":
		sort.SliceStable(out, func(i, j int) bool {
			if out[i].Priority != out[j].Priority {
				return out[i].Priority < out[j].Priority
			}
			return out[i].ID < out[j].ID
		})
	case "due":
		sort.SliceStable(out, func(i, j int) bool {
			di, dj := out[i].Due, out[j].Due
			if di == nil && dj == nil {
				return out[i].ID < out[j].ID
			}
			if di == nil {
				return false // no due date comes last
			}
			if dj == nil {
				return true
			}
			if !di.Equal(*dj) {
				return di.Before(*dj)
			}
			return out[i].ID < out[j].ID
		})
	default:
		return nil, fmt.Errorf("unknown sort key %q", o.SortBy)
	}
	return out, nil
}
