// FormatTask renders one list line: "#<id> [x| ] P<priority> <title>" with
// " (due YYYY-MM-DD)" and " [tag1,tag2]" appended when present.
func FormatTask(t model.Task) string {
	mark := " "
	if t.Done {
		mark = "x"
	}
	line := fmt.Sprintf("#%d [%s] P%d %s", t.ID, mark, t.Priority, t.Title)
	if t.Due != nil {
		line += fmt.Sprintf(" (due %s)", t.Due.Format("2006-01-02"))
	}
	if len(t.Tags) > 0 {
		line += fmt.Sprintf(" [%s]", stringsJoin(t.Tags, ","))
	}
	return line
}
